const rotas = $json.routes;
if (!rotas || rotas.length === 0 || !rotas[0].distanceMeters) {
  return [{ json: { disponivel: false, origem_calculo: 'distancia_real', motivo: 'Não foi possível calcular a rota até esse endereço' } }];
}
const distanciaKm = rotas[0].distanceMeters / 1000;
return [{ json: { distancia_km: distanciaKm, prossegue: true } }];

// distancia_km nunca sai daqui: e dado interno (o mesmo motivo pelo qual
// consultar_zona_entrega tambem nao expoe). O agente so precisa do
// resultado final (disponivel/valor/prazo), nao da distancia bruta.
const modalidade = $('When Executed by Another Workflow').item.json.p_modalidade || 'expressa';
const zona = $input.item.json;

if (!zona || !zona.zona_id) {
  return [{ json: { disponivel: false, zona_nome: null, valor_frete: null, valor_frete_cheio: null, frete_gratis: null, prazo_estimado_min: null, modalidade: null, motivo: 'Fora da área de entrega' } }];
}

if (modalidade === 'economica') {
  if (zona.economico_valor == null) {
    return [{ json: { disponivel: false, zona_nome: null, valor_frete: null, valor_frete_cheio: null, frete_gratis: null, prazo_estimado_min: null, modalidade: null, motivo: 'Frete econômico não disponível para esta loja' } }];
  }
  return [{ json: {
    disponivel: true,
    zona_nome: zona.zona_nome,
    valor_frete: zona.economico_valor,
    valor_frete_cheio: zona.economico_valor,
    frete_gratis: false,
    prazo_estimado_min: [zona.economico_prazo_dias * 24 * 60, zona.economico_prazo_dias * 24 * 60],
    modalidade: 'economica',
    motivo: null,
  }}];
}

return [{ json: {
  disponivel: true,
  zona_nome: zona.zona_nome,
  valor_frete: zona.valor,
  valor_frete_cheio: zona.valor_cheio,
  frete_gratis: zona.frete_gratis,
  prazo_estimado_min: [zona.estimativa_min_min, zona.estimativa_min_max],
  modalidade: 'expressa',
  motivo: null,
}}];

function tryGet(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}
const trigger = $('When Executed by Another Workflow').item.json;
const resultado = tryGet('Montar Resultado') || tryGet('Sem Endereço') || tryGet('Rota Não Encontrada');
const blacklist = ['p_empresa_id','p_cliente_id','p_conversa_id','p_mensagem_id','p_atendimento_id'];
const input = {};
for (const k of Object.keys(trigger || {})) {
  if (!blacklist.includes(k)) input[k] = trigger[k];
}
return [{ json: {
  empresa_id: trigger.p_empresa_id,
  conversa_id: trigger.p_conversa_id || null,
  mensagem_id: trigger.p_mensagem_id || null,
  atendimento_id: trigger.p_atendimento_id || null,
  tool_nome: 'calcular_frete',
  detalhes: JSON.stringify({ input, output: resultado }),
  resultado_original: resultado,
} }];

